<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="author" content="Jean Pierre Alfredo Jara Espinoza">
  <meta name="description" content="Portafolio de Jean Pierre Jara Espinoza, estudiante de Ingeniería de Sistemas e Informática. Proyectos, pasantía, experiencia y CV.">
  <meta name="theme-color" content="#f9f8f2">
  <title>Jean Pierre Jara Espinoza · Portafolio</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
  <style>
    :root {
      --paper: #f9f8f2;
      --white: #fffefa;
      --ink: #172c25;
      --muted: #455a51;
      --green: #24573f;
      --sage: #e2eddf;
      --lime: #e1ebae;
      --blue: #e4eafa;
      --line: #d8dfd4;
      --display: "Instrument Serif", Georgia, serif;
      --body: "DM Sans", system-ui, sans-serif;
    }

    *, *::before, *::after { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body { margin: 0; color: var(--ink); background: var(--paper); font: 1rem/1.65 var(--body); }
    button { font: inherit; }
    a { color: inherit; text-underline-offset: .22em; }
    img { display: block; width: 100%; height: auto; }
    h1, h2, h3, p, figure { margin: 0; }
    h1, h2, h3 { text-wrap: balance; }
    :focus-visible { outline: 3px solid #3e7759; outline-offset: 4px; }
    [id] { scroll-margin-top: 6rem; }
    .wrap { width: min(calc(100% - 3rem), 1136px); margin-inline: auto; }
    .skip { position: fixed; z-index: 10; left: 1rem; top: 1rem; padding: .5rem 1rem; background: var(--white); transform: translateY(-200%); }
    .skip:focus { transform: none; }

    .header { position: sticky; top: 0; z-index: 5; background: #f9f8f2f5; border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); }
    .header-inner { min-height: 70px; display: flex; justify-content: space-between; align-items: center; gap: 1.1rem; }
    .brand { display: inline-flex; align-items: center; gap: .65rem; font-weight: 700; text-decoration: none; white-space: nowrap; }
    .monogram { display: grid; place-items: center; width: 2.25rem; aspect-ratio: 1; color: var(--green); background: var(--sage); border: 1px solid #c7dac8; border-radius: 50%; font: 1.15rem/1 var(--display); }
    nav ul { display: flex; flex-wrap: wrap; gap: .65rem clamp(.75rem, 2vw, 1.6rem); list-style: none; margin: 0; padding: 0; }
    nav a { color: var(--muted); font-size: .88rem; font-weight: 700; text-decoration: none; }
    nav a:hover { color: var(--green); text-decoration: underline; }

    .hero { display: grid; grid-template-columns: minmax(0, 1.32fr) minmax(0, 1fr); gap: clamp(1.6rem, 6vw, 6rem); align-items: center; padding-block: clamp(2.7rem, 7vw, 6.25rem) clamp(3rem, 7vw, 5.5rem); }
    .hero-copy { animation: arrive .7s ease-out both; }
    .overline { display: flex; align-items: center; gap: .55rem; margin-bottom: .9rem; color: var(--green); font-size: .73rem; font-weight: 700; letter-spacing: .12em; line-height: 1.35; text-transform: uppercase; }
    .overline::before { content: ""; width: .55rem; height: .55rem; flex: none; border-radius: 50%; background: #77a36b; }
    h1 { font: 400 clamp(3.7rem, 8vw, 7.1rem)/.86 var(--display); letter-spacing: -.025em; }
    h1 em { display: block; color: var(--green); font-weight: 400; }
    .intro { max-width: 49ch; margin-top: 1.5rem; color: var(--muted); font-size: clamp(1rem, 1.5vw, 1.16rem); }
    .actions { display: flex; flex-wrap: wrap; gap: .65rem; margin-top: 1.45rem; }
    .button { display: inline-flex; align-items: center; justify-content: center; gap: .65rem; min-height: 46px; padding: .6rem 1.05rem; border: 1px solid var(--green); border-radius: 100px; color: var(--green); background: transparent; cursor: pointer; font-size: .88rem; font-weight: 700; text-decoration: none; transition: transform .22s ease, background .22s ease; }
    .button[hidden] { display: none; }
    .button.primary { color: #fff; background: var(--green); }
    .button:hover { transform: translateY(-2px); background: var(--sage); }
    .button.primary:hover { background: #19422e; }
    .portrait { position: relative; isolation: isolate; width: 100%; max-width: 390px; justify-self: center; padding: .65rem .65rem 0; animation: arrive .75s .12s ease-out both; }
    .portrait::before { content: ""; position: absolute; z-index: -1; inset: -2% -5% 6% 4%; border-radius: 49% 49% 20px 20px; background: var(--sage); transform: rotate(7deg); }
    .portrait::after { content: ""; position: absolute; z-index: 1; width: clamp(34px, 7vw, 72px); aspect-ratio: 1; right: -4%; top: 8%; border-radius: 50%; background: var(--lime); border: 5px solid var(--paper); pointer-events: none; }
    .portrait img { aspect-ratio: 5 / 6; object-fit: cover; border-radius: 46% 46% 17px 17px / 28% 28% 17px 17px; }
    @keyframes arrive { from { opacity: .72; transform: translateY(12px); } to { opacity: 1; transform: none; } }

    .section { padding-block: clamp(3rem, 6vw, 5.35rem); border-top: 1px solid var(--line); }
    .section h2 { font: 400 clamp(2.6rem, 5vw, 4.75rem)/.98 var(--display); letter-spacing: -.015em; }
    .section-intro { max-width: 62ch; margin-top: .75rem; color: var(--muted); }
    .project { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.08fr); align-items: stretch; margin-top: 1.65rem; overflow: hidden; border: 1px solid var(--line); border-radius: 24px; background: var(--white); }
    .project-copy { align-self: center; padding: clamp(1.4rem, 4vw, 3.25rem); }
    .meta { color: var(--green); font-size: .75rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
    .project h3, .card h3, .resume-side h3, .application h3 { margin-top: .28rem; font: 400 clamp(1.95rem, 3.6vw, 3.15rem)/1.05 var(--display); }
    .project p + p, .card p + p { margin-top: .65rem; }
    .project h3 + p, .card h3 + p { margin-top: .65rem; }
    .copy { color: var(--muted); }
    .tags { display: flex; flex-wrap: wrap; gap: .35rem; padding: 0; margin: 1rem 0 0; list-style: none; }
    .tags li { padding: .25rem .64rem; border: 1px solid #cfddd0; border-radius: 100px; background: #f1f6ee; color: var(--green); font-size: .76rem; font-weight: 700; }
    .photo { display: block; border: 0; cursor: zoom-in; padding: 0; width: 100%; overflow: hidden; background: var(--sage); }
    .photo:focus-visible { outline-offset: -5px; }
    .photo { transition: box-shadow .22s ease, transform .22s ease; }
    .photo:hover { transform: translateY(-2px); box-shadow: 0 5px 12px #1d392123; }
    .photo-pair { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); gap: .75rem; align-content: center; padding: clamp(.8rem, 2vw, 1.5rem); }
    .pet-media { background: radial-gradient(ellipse at 70% 40%, #f6f8e4 0, #e6efda 48%, #d9e8d4 100%); }
    .internship-media { background: #eaf0fa; }
    .photo-pair .photo { height: clamp(10rem, 23vw, 17rem); border-radius: 12px; background: #ffffff85; }
    .photo-pair img { width: 100%; height: 100%; object-fit: contain; }
    .photo-pair figcaption { margin-top: .4rem; color: var(--muted); font-size: .76rem; line-height: 1.4; }
    .two-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; margin-top: 1rem; }
    .card { padding: clamp(1.25rem, 3vw, 2rem); border: 1px solid var(--line); border-radius: 19px; background: var(--white); }
    .card h3 { font-size: clamp(1.75rem, 3vw, 2.35rem); }
    .card.soft { background: #eef2fb; border-color: #dce2ef; }
    .experience { grid-template-columns: minmax(0, 1.04fr) minmax(0, 1fr); margin-top: 1.55rem; }

    .cv-heading { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: .9rem; }
    .resume { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(0, .85fr); gap: 1rem; margin-top: 1.45rem; }
    .resume-side { padding: clamp(1.3rem, 3.6vw, 2.25rem); border: 1px solid var(--line); border-radius: 20px; background: var(--white); }
    .resume-side.skills { background: var(--sage); border-color: #cedecd; }
    .resume-side h3 { margin: 0 0 .55rem; font-size: clamp(1.85rem, 3vw, 2.6rem); }
    .resume-side h3:not(:first-child) { margin-top: 1.25rem; padding-top: 1rem; border-top: 1px solid var(--line); }
    .resume-list { list-style: none; padding: 0; margin: 0; }
    .resume-list li + li { margin-top: .62rem; }
    .resume-list span { display: block; color: var(--muted); font-size: .88rem; }
    .skills dl { margin: 0; }
    .skills dl div { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; padding-block: .48rem; border-bottom: 1px solid #c7d9c6; }
    .skills dt { font-weight: 700; }
    .skills dd { margin: 0; color: var(--muted); font-size: .9rem; text-align: right; }
    .print-name { display: none; }

    .application-banner { padding: clamp(1.3rem, 4vw, 3.25rem); border-radius: 24px; background: var(--blue); border: 1px solid #d6e0f1; }
    .application-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .65rem; margin-top: 1.25rem; }
    .application { padding: .9rem; border: 1px solid #cbd9eb; border-radius: 14px; background: #f9faff; }
    .application h3 { margin-top: 0; font-size: 1.6rem; }
    .application p { margin-top: .25rem; color: var(--muted); font-size: .83rem; line-height: 1.45; }
    .footer { border-top: 1px solid var(--line); padding-block: 1.4rem; }
    .footer .wrap { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: .45rem 1rem; }
    .footer p, .footer a { color: var(--muted); font-size: .88rem; }

    dialog { max-width: min(92vw, 760px); padding: .8rem; border: 1px solid var(--line); border-radius: 18px; color: var(--ink); background: var(--paper); }
    dialog::backdrop { background: #14251cd9; }
    dialog form { display: flex; justify-content: end; margin-bottom: .55rem; }
    dialog img { width: auto; max-width: 100%; max-height: 72vh; margin-inline: auto; border-radius: 10px; object-fit: contain; }
    .revealed { animation: arrive .55s ease-out; }

    @media (max-width: 760px) {
      .hero { grid-template-columns: minmax(0, 1.08fr) minmax(0, .92fr); gap: 1.1rem; }
      h1 { font-size: clamp(3.15rem, 8.4vw, 5rem); }
      .application-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    @media (max-width: 580px) {
      .wrap { width: calc(100% - 2rem); }
      [id] { scroll-margin-top: 8rem; }
      .header-inner { flex-direction: column; align-items: start; gap: .3rem; padding-block: .45rem .55rem; }
      nav ul { gap: .2rem .85rem; }
      nav a { font-size: .78rem; }
      .hero, .project, .two-columns, .resume { grid-template-columns: minmax(0, 1fr); }
      .hero { gap: 1.5rem; }
      .portrait { width: min(85%, 280px); }
    }

    @media (max-width: 340px) {
      .application-grid { grid-template-columns: minmax(0, 1fr); }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { scroll-behavior: auto !important; animation: none !important; transition: none !important; }
    }

    @media print {
      @page { margin: 15mm; }
      body { background: white; color: black; font-size: 10.5pt; }
      .header, .skip, .footer, main > :not(#cv), #print-cv, dialog { display: none !important; }
      #cv { width: 100%; padding: 0; border: 0; }
      #cv .section-intro { color: black; }
      #cv h2 { font-size: 22pt; }
      .print-name { display: block; margin-bottom: .55rem; font-size: 17pt; font-weight: bold; }
      .resume { display: block; margin-top: 1rem; }
      .resume-side, .resume-side.skills { padding: 0; border: 0; background: white; }
      .resume-side + .resume-side { margin-top: 1rem; }
      .resume-side h3, .resume-side h3:not(:first-child) { padding: 0; border: 0; font-size: 14pt; }
      .resume-list span, .skills dd { color: black; }
      .skills dl div { padding-block: .17rem; max-width: 22rem; }
    }
  </style>
</head>
<body id="inicio">
  <a class="skip" href="#contenido">Ir al contenido</a>
  <header class="header">
    <div class="wrap header-inner">
      <a class="brand" href="#inicio"><span class="monogram" aria-hidden="true">JP</span> Jean Pierre</a>
      <nav aria-label="Navegación principal">
        <ul>
          <li><a href="#proyectos">Proyectos</a></li>
          <li><a href="#experiencia">Experiencia</a></li>
          <li><a href="#cv">CV</a></li>
          <li><a href="#postulaciones">Postulaciones</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="contenido">
    <section class="wrap hero" aria-labelledby="nombre">
      <div class="hero-copy">
        <p class="overline">Portafolio académico · Chimbote, Perú</p>
        <h1 id="nombre">Jean Pierre <em>Jara Espinoza</em></h1>
        <p class="intro">Estudio Ingeniería de Sistemas e Informática en la Universidad Nacional del Santa. Quiero desarrollarme como analista de datos y también me interesa la gestión de proyectos de TI.</p>
        <div class="actions">
          <a class="button primary" href="#proyectos">Ver mis proyectos <span aria-hidden="true">↘</span></a>
          <a class="button" href="#cv">Consultar mi CV</a>
        </div>
      </div>
      <figure class="portrait">
        <img src="data:image/webp;base64," width="650" height="751" fetchpriority="high" alt="Retrato de Jean Pierre Jara Espinoza">
      </figure>
    </section>

    <section class="wrap section" id="proyectos" aria-labelledby="titulo-proyectos">
      <h2 id="titulo-proyectos">Proyectos</h2>
      <article class="project" data-reveal>
        <div class="project-copy">
          <p class="meta">Desarrollo móvil · Visión por computadora</p>
          <h3>PetPoint</h3>
          <p class="copy">PetPoint es una app Android que desarrollamos en equipo para reportar mascotas perdidas o encontradas.</p>
          <p class="copy">Mi aporte fue integrar el flujo que detecta y recorta a la mascota en una foto y la compara con imágenes de otros reportes para sugerir coincidencias.</p>
          <ul class="tags" aria-label="Tecnologías del proyecto">
            <li>Android</li><li>YOLOv8</li><li>DINOv2</li>
          </ul>
        </div>
        <div class="photo-pair pet-media">
          <figure>
            <button type="button" class="photo" data-photo aria-label="Ampliar la foto del equipo de PetPoint">
              <img src="data:image/webp;base64," width="960" height="640" loading="lazy" alt="Equipo de PetPoint con camisetas de Incuba UNS">
            </button>
            <figcaption>Mi equipo de PetPoint en Incuba UNS.</figcaption>
          </figure>
          <figure>
            <button type="button" class="photo" data-photo aria-label="Ampliar la portada de PetPoint">
              <img src="data:image/webp;base64," width="465" height="879" loading="lazy" alt="Pantalla de bienvenida de PetPoint con su logotipo">
            </button>
            <figcaption>Pantalla de bienvenida de la app.</figcaption>
          </figure>
        </div>
      </article>
      <div class="two-columns">
        <article class="card" data-reveal>
          <p class="meta">Hackatón nacional · 2026</p>
          <h3>Alerta Albarracina</h3>
          <p class="copy">En TransformaGob 2026 trabajé con mi equipo en un prototipo de seguridad ciudadana. Definimos el problema, priorizamos las funciones y presentamos la propuesta durante el evento.</p>
        </article>
        <article class="card soft" data-reveal>
          <p class="meta">Proyecto de bachiller</p>
          <h3>Consulta de boletas para pensionistas</h3>
          <p class="copy">A partir de una necesidad que conocí durante mis prácticas, planteé una propuesta de sistema web para facilitar la consulta de boletas de pago de pensionistas titulares y sobrevivientes de la UGEL Santa.</p>
        </article>
      </div>
    </section>

    <section class="wrap section" id="experiencia" aria-labelledby="titulo-experiencia">
      <h2 id="titulo-experiencia">Experiencia</h2>
      <article class="project experience" data-reveal>
        <div class="photo-pair internship-media">
          <figure>
            <button type="button" class="photo" data-photo aria-label="Ampliar la foto en el campus de la UNSA">
              <img src="data:image/webp;base64," width="720" height="574" loading="lazy" alt="El grupo de la pasantía junto a las letras UNSA en el campus de Arequipa">
            </button>
            <figcaption>Con mis compañeros en el campus de la UNSA.</figcaption>
          </figure>
          <figure>
            <button type="button" class="photo" data-photo aria-label="Ampliar la foto del grupo en CiTeSoft">
              <img src="data:image/webp;base64," width="680" height="1209" loading="lazy" alt="Jean Pierre con sus compañeros frente al letrero de CiTeSoft">
            </button>
            <figcaption>En CiTeSoft durante la pasantía nacional.</figcaption>
          </figure>
        </div>
        <div class="project-copy">
          <p class="meta">Arequipa · Septiembre a octubre de 2026</p>
          <h3>Pasantía en la UNSA</h3>
          <p class="copy">Durante mi pasantía en la Universidad Nacional de San Agustín de Arequipa participé en un proyecto de IA generativa para que los docentes puedan elaborar cuestionarios a partir de sílabos y otros materiales académicos.</p>
        </div>
      </article>
      <div class="two-columns">
        <article class="card" data-reveal>
          <p class="meta">Prácticas preprofesionales</p>
          <h3>UGEL Santa</h3>
          <p class="copy">Apoyé en la gestión de resoluciones docentes, el seguimiento de expedientes en el sistema institucional y la orientación a docentes durante la entrega de sus documentos.</p>
        </article>
        <article class="card soft" data-reveal>
          <p class="meta">Voluntariado universitario</p>
          <h3>Incuba UNS</h3>
          <p class="copy">Apoyé en la organización y la logística de actividades del equipo de Incuba UNS.</p>
        </article>
      </div>
    </section>

    <section class="wrap section" id="cv" aria-labelledby="titulo-cv">
      <div class="cv-heading">
        <div>
          <p class="print-name">Jean Pierre Alfredo Jara Espinoza</p>
          <h2 id="titulo-cv">Resumen de mi CV</h2>
          <p class="section-intro">Estudiante de Ingeniería de Sistemas e Informática · Universidad Nacional del Santa</p>
        </div>
        <button class="button" id="print-cv" type="button" hidden>Imprimir o guardar como PDF</button>
      </div>
      <div class="resume" data-reveal>
        <div class="resume-side">
          <h3>Experiencia</h3>
          <ul class="resume-list">
            <li><strong>UGEL Santa</strong><span>Prácticas en gestión de resoluciones docentes y seguimiento de expedientes.</span></li>
            <li><strong>Universidad Nacional de San Agustín de Arequipa</strong><span>Pasantía de investigación en cuestionarios académicos con IA generativa.</span></li>
            <li><strong>PetPoint y TransformaGob 2026</strong><span>Integración de modelos de visión por computadora en una app Android y desarrollo en equipo de un prototipo para una hackatón.</span></li>
          </ul>
          <h3>Formación complementaria</h3>
          <ul class="resume-list">
            <li><strong>IBM Data Analyst Professional Certificate</strong><span>En curso · Coursera</span></li>
            <li><strong>Power BI básico y Ofimática Empresarial</strong><span>UNI y CECOMP · 2025</span></li>
          </ul>
        </div>
        <div class="resume-side skills">
          <h3>Herramientas</h3>
          <dl>
            <div><dt>Excel</dt><dd>Intermedio</dd></div>
            <div><dt>SQL Server</dt><dd>Básico</dd></div>
            <div><dt>Power BI</dt><dd>Básico</dd></div>
          </dl>
          <h3>Áreas de interés</h3>
          <p class="copy">Análisis de datos, inteligencia de negocios y gestión de proyectos de TI.</p>
        </div>
      </div>
    </section>

    <section class="wrap section" id="postulaciones" aria-labelledby="titulo-postulaciones">
      <div class="application-banner" data-reveal>
        <h2 id="titulo-postulaciones">Postulaciones</h2>
        <p class="section-intro">He postulado a programas de prácticas en banca e industria. Me interesan las oportunidades donde pueda aplicar lo aprendido en análisis de datos y conocer cómo se gestionan proyectos de TI.</p>
        <div class="application-grid" aria-label="Programas a los que he postulado">
          <article class="application"><h3>Interbank</h3><p>Programa de Prácticas 2027</p></article>
          <article class="application"><h3>COFIDE</h3><p>Buscando Talento COFIDE 2027</p></article>
          <article class="application"><h3>BBVA</h3><p>Programa de Prácticas</p></article>
          <article class="application"><h3>Repsol</h3><p>Programa de Prácticas</p></article>
        </div>
      </div>
    </section>
  </main>

  <footer class="footer">
    <div class="wrap">
      <p>Jean Pierre Alfredo Jara Espinoza · Universidad Nacional del Santa</p>
      <a href="#inicio">Volver arriba ↑</a>
    </div>
  </footer>

  <dialog id="foto-ampliada" aria-label="Imagen ampliada">
    <form method="dialog"><button class="button" type="submit">Cerrar <span aria-hidden="true">×</span></button></form>
    <img alt="">
  </dialog>

  <script>
    const motion = matchMedia("(prefers-reduced-motion: reduce)");
    if ("IntersectionObserver" in window && !motion.matches) {
      const observer = new IntersectionObserver((entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          entry.target.classList.add("revealed");
          observer.unobserve(entry.target);
        }
      }, { rootMargin: "0px 0px -10% 0px" });
      for (const element of document.querySelectorAll("[data-reveal]")) {
        if (element.getBoundingClientRect().top < innerHeight) continue;
        observer.observe(element);
      }
    }

    const photoDialog = document.querySelector("#foto-ampliada");
    const enlargedPhoto = photoDialog.querySelector("img");
    for (const opener of document.querySelectorAll("[data-photo]")) {
      opener.addEventListener("click", () => {
        const source = opener.querySelector("img");
        enlargedPhoto.src = source.src;
        enlargedPhoto.alt = source.alt;
        photoDialog.showModal();
      });
    }

    const printButton = document.querySelector("#print-cv");
    printButton.hidden = false;
    printButton.addEventListener("click", () => window.print());
  </script>
</body>
</html>
